import { execFileSync } from "node:child_process";
import { mkdtempSync, readFileSync, rmSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";

// Compare generated bytes with the working copy. Comparing with Git HEAD
// incorrectly rejects a synchronized client whenever its schema is being edited.
const directory = mkdtempSync(join(tmpdir(), "contractor-public-client-"));
try {
  const output = join(directory, "public.ts");
  execFileSync(
    "openapi-typescript",
    ["../api/openapi/contractor-public-v1.yaml", "-o", output],
    { stdio: "inherit" },
  );
  if (
    !readFileSync(output).equals(readFileSync("src/api/generated/public.ts"))
  ) {
    throw new Error("Public client is stale. Run pnpm generate.");
  }
} finally {
  rmSync(directory, { recursive: true, force: true });
}
